function renderErrors(){for(const node of globalThis.document?.querySelectorAll?.('[data-action-error]')||[]){const error=ui.actionErrors[node.dataset.actionError];if(!error){node.hidden=true;continue;}const c=findCard(error.act,error.id,error.section),count=error.amount==='max'?'max':Number(error.amount)||1,ready=allowed(error.act,c)&&(!['build','craft','refine','hunt'].includes(error.act)||batchPreview(c,count,vm).affordable);if(ready){delete ui.actionErrors[node.dataset.actionError];node.hidden=true;continue;}const bill=c&&['build','craft','refine','hunt'].includes(error.act)&&count!=='max'?batchPreview(c,count,vm).costs:c?.costs||[],missing=bill.filter(x=>x.owned<x.value);const markup=`<p>${esc(error.message)}</p>${missing.map(x=>`<p>${esc(x.name)}还差 ${fmt(x.value-x.owned,2)}${resourceRemedy(x.id,x.value)}</p>`).join('')}`;node.hidden=false;if(node.innerHTML!==markup)node.innerHTML=markup;}}
function changeAmount(event){const key=event.target.dataset?.actionAmount;if(!key)return;delete ui.actionErrors[key];ui.amounts[key]=event.target.value==='max'?'max':Number(event.target.value);const button=event.target.closest('.action-row')?.querySelector('.primary[data-act]');if(button)button.dataset.amount=String(ui.amounts[key]);updateLive();}

function card(c,section){return `<article class="discovery-card" tabindex="-1" data-research-card="${section}:${c.id}"><button class="card-picture" data-detail="${section}:${c.id}" aria-label="查看${esc(c.name)}详情">${artFor(c,section)}</button><div class="card-copy"><h2>${esc(c.name)}</h2><button class="text-button detail-entry" data-detail="${section}:${c.id}">详情 ›</button><span class="decision-state ${decisionState(c,vm).kind}" data-card-state="${section}:${c.id}">${decisionState(c,vm).label}</span><p class="card-benefit">${esc(forestBenefits(c,section,vm))}</p></div>${!c.completed?costs(c,section):''}${actionButtons(c,section)}${!c.completed?trackButton(c,section):''}</article>`;}
function home(){return `<section class="world-board" aria-label="小熊家园"><div class="world-toolbar"><button class="icon-button" data-nav="map" aria-label="打开森林地图">${icon('map')}</button><div class="scene-tabs" aria-label="家园区域"></div><span class="scene-status"></span><button class="text-button phase-entry" data-command="chapter-progress">成长路线</button><button class="text-button map-toggle" data-command="map-toggle" aria-expanded="${!settings.mapCollapsed}">${settings.mapCollapsed?"展开地图":"收起地图"}</button></div><div class="world-scene" tabindex="0" aria-label="可上下滚动的家园地图"><div class="continuous-map" style="background-image:url('${esc(art.scenery?.background||art.background)}')"></div><button class="scene-plan" data-nav="build" data-build-target="hive" data-flow="true" ${vm.buildings.some(c=>c.owned>0)?'hidden':''}>${image('buildings','hive')}<span>第一座蜂箱</span><small>预留的位置 · 查看建造</small></button></div></section><div id="completion-slot"></div><div class="home-controls"><button id="guide" class="guide" data-nav="build" data-flow="true"></button><div class="gather-zone"><button data-act="gather" data-id="honey"><span>${image('resources','honey')}</span><span><b>采集蜂蜜</b><small>+1 蜂蜜</small></span></button><button class="secondary" data-act="refine" data-id="wood"><span>${image('resources','wood')}</span><span><b>采木</b><small id="refine-cost"></small></span></button></div><div class="action-error" data-action-error="actions:honey" role="status" hidden></div><div class="action-error" data-action-error="crafts:wood" role="status" hidden></div><div id="observe-slot"></div></div>`;}
function updateScene(){const board=app.querySelector('.world-board');if(!board)return;const groups=visibleRegions(vm);if(!groups.some(r=>r.id===ui.region))ui.region=groups[0].id;const tabs=board.querySelector('.scene-tabs');const tabsKey=groups.map(r=>r.id).join()+ui.region;if(tabs.dataset.key!==tabsKey){tabs.innerHTML=groups.map(r=>`<button data-region="${r.id}" class="${r.id===ui.region?'selected':''}" aria-pressed="${r.id===ui.region}">${r.name}</button>`).join('');tabs.dataset.key=tabsKey;}
 const scene=board.querySelector('.world-scene'),map=board.querySelector('.continuous-map');scene.classList.toggle('scene-paused',!!stopped());const {buildings:lots,height}=sceneLayout(vm,ui.region),built=lots.map(l=>l.card);const sceneIds=new Set(built.map(c=>c.id));for(const node of map.querySelectorAll('[data-scene-building]'))if(!sceneIds.has(node.dataset.sceneBuilding))node.remove();
 for(const {card:c,x,y} of lots){const pos={x,y};let el=map.querySelector(`[data-scene-building="${c.id}"]`);if(!el){el=document.createElement('button');el.className='placed-building';el.dataset.sceneBuilding=c.id;el.dataset.detail='buildings:'+c.id;el.innerHTML='<span class="building-ground"></span>'+buildingImage(c)+'<span class="building-count"></span><span class="building-label"></span>';map.append(el);}el.style.setProperty('--x',pos.x+'%');el.style.setProperty('--y',pos.y+'px');el.setAttribute('aria-label',`${c.name} ${fmt(c.owned)} 座，查看详情`);const newImage=buildingImage(c);const imageNode=el.querySelector('img');if(imageNode&&newImage){const url=(c.owned>=({hive:5,hut:3,library:3,barn:3,lumberMill:3,workshop:3,warehouse:3}[c.id]||Infinity)&&art.growth?.[c.id])?art.growth[c.id]:art.buildings[c.id];if(imageNode.getAttribute('src')!==url){imageNode.dataset.artUrl=url;imageNode.src=url;}}const condition=buildingCondition(c,vm);el.querySelector('.building-label').textContent=c.name+(condition?' · '+condition:'');el.classList.toggle('building-alert',!!condition);el.setAttribute('aria-label',`${c.name} ${fmt(c.owned)} 座${condition?'，'+condition:''}，查看详情`);const count=el.querySelector('.building-count');count.textContent='×'+fmt(c.owned);count.hidden=c.owned<2;}
 const {actors,height:actorHeight}=sceneActors(vm,ui.region,{width:map.clientWidth||336,viewportWidth:globalThis.innerWidth||336,paused:!!stopped()});map.style.setProperty('--map-height',Math.max(height,actorHeight)+'px');
 for(const node of map.querySelectorAll('[data-bear]'))if(!actors.some(a=>String(a.bear.id)===node.dataset.bear))node.remove();for(const a of actors){let el=map.querySelector(`[data-bear="${a.bear.id}"]`);if(!el){el=document.createElement('button');el.className='scene-worker';el.dataset.bear=String(a.bear.id);el.innerHTML='<span class="worker-body"></span><span class="worker-label"></span>';map.append(el);}if(el.dataset.job!==a.job){el.querySelector('.worker-body').innerHTML=(image('workers',a.job,'worker-ready','ready')||image('bears','idleFront','worker-ready'))+(image('workers',a.job,'worker-work','work')||image('bears','idleFront','worker-work'));el.dataset.job=a.job;}el.style.setProperty('--x',a.x+'%');el.style.setProperty('--y',a.y+'px');el.classList.toggle('is-working',a.working);const jobName=vm.jobs.find(j=>j.id===a.job)?.name||'林间散步';el.querySelector('.worker-label').textContent=jobName+(a.count>1?' ×'+a.count:'');el.setAttribute('aria-label',`${a.bear.name||'小熊'}，${jobName}，${a.working?'工作中':'休息中'}，点按聊聊`);}
 const plan=board.querySelector('.scene-plan');if(plan)plan.hidden=vm.buildings.some(c=>c.owned>0);revealBuilt(scene,lots);syncSceneFocus();writeText('.phase-entry','成长 '+Math.min(4,forestStages(vm).filter(s=>s.done).length+1)+'/4');writeText('.scene-status',vm.bears.value?`${fmt(vm.bears.value)} 只伙伴`:'');updateGuide();const completed=chapterComplete(vm);const slot=app.querySelector('#completion-slot');if(slot.firstElementChild)slot.innerHTML='';if(completed&&!completionWasShown){completionWasShown=true;notify('家园长成了！第一章的林间故事已经完成。',6000);}}
function revealBuilt(scene,lots){
 if(!ui.revealBuilding||dialog)return;const target=lots.find(l=>l.card.id===ui.revealBuilding);if(!target)return;
 const top=Math.max(0,target.y-scene.clientHeight/2),reduced=settings.reducedMotion||globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
 ui.revealBuilding=null;ui.scrolls[pageKey()]=top;scene.scrollTo({top,behavior:reduced?'instant':'smooth'});
}
function updateGuide(){const guide=app.querySelector('#guide');if(!guide)return;const g=forestGuidance(vm,settings.tracked),complete=chapterComplete(vm);if(complete){g.title='第一章 · 家园长成了';g.text='伙伴们继续在这里生活。点开看看这份收获。';}const html=(g.card?artFor(g.card,g.section)||image('resources','science'):image('bears','wave'))+`<span><b>${esc(g.title)}</b><small>${esc(g.text)}</small>${progressMarkup(g)}</span>`;if(guide.innerHTML!==html)guide.innerHTML=html;for(const key of ['nav','command','resource','buildTarget','researchChoice','jobTarget','researchTarget'])delete guide.dataset[key];if(complete){guide.dataset.command='completion';delete guide.dataset.nav;}else if(g.command){guide.dataset.command=g.command;if(g.resource)guide.dataset.resource=g.resource;}else{guide.dataset.nav=g.page;if(g.page==='research'){guide.dataset.researchChoice=g.section;if(g.card)guide.dataset.researchTarget=g.card.id;}if(g.job)guide.dataset.jobTarget=g.job;if(g.page==='build'&&g.card)guide.dataset.buildTarget=g.card.id;}const refine=vm.actions?.find(c=>c.type==='refine')||vm.crafts.find(c=>c.id==='wood');writeText('#refine-cost',(refine?.costs||[]).map(c=>`${fmt(c.value)} ${c.name}`).join(' + '));const observe=vm.actions?.find(c=>c.type==='observe'&&c.unlocked);const observeSlot=app.querySelector('#observe-slot');if(observeSlot){const markup=observe?`<button class="secondary" data-act="observe" data-id="${observe.id}">记录林间的发现</button>`:'';if(observeSlot.innerHTML!==markup)observeSlot.innerHTML=markup;}}
function buildPage(){const queueEntry=`<button class="queue-entry" data-nav="build/queue" aria-label="打开建造队列"><span>建造队列</span><b data-queue-count>${fmt(vm.queue?.used||0)}/${fmt(vm.queue?.capacity||3)}</b>${icon('arrow')}</button>`;const cards=vm.buildings.filter(known);const c=cards.find(c=>c.id===ui.buildChoice)||cards[0];if(!c)return heading('建造',queueEntry)+empty('先去林间收集一点蜂蜜吧。');ui.buildChoice=c.id;return heading('建造',queueEntry)+`<div class="building-picker" aria-label="选择建筑">${cards.map(b=>`<button class="building-option ${b.id===c.id?'selected':''}" data-build-choice="${b.id}" aria-pressed="${b.id===c.id}">${buildingImage(b)}<b>${esc(b.name)}</b><span class="decision-state ${decisionState(b,vm).kind}" data-build-state="${b.id}">${decisionState(b,vm).label}</span>${b.owned?`<small>×${fmt(b.owned)}</small>`:''}</button>`).join('')}</div>`+queueSummary()+`<section class="build-station"><button class="build-showcase" data-detail="buildings:${c.id}" aria-label="查看${esc(c.name)}详情">${buildingImage(c)}</button><div class="build-caption"><h2>${esc(c.name)}</h2><button class="text-button detail-entry" data-detail="buildings:${c.id}">详情 ›</button><span class="owned">已建 <b data-owned="${c.id}">${fmt(c.owned)}</b> 座</span><p>${esc(Array.isArray(c.effects)?c.effects.join(' · '):c.effects||c.description)}</p></div>${['hut','logHouse'].includes(c.id)?`<p class="housing-warning">入住口粮：每只 ${fmt(vm.bears.foodPerBear||4.25,2)} 蜂蜜/秒。当前净产 ${signed(getResource(vm,'honey').rate)}/秒。</p>`:''}${costs(c,'buildings')}<p class="building-outcome" data-building-outcome="${c.id}">${esc(buildingOutcome(c))}</p>${actionButtons(c,'buildings')}${trackButton(c,'buildings')}</section>${c.owned?`<details class="fold"><summary>管理这处建筑</summary><div class="fold-content"><p class="detail-note">${c.toggleable?'可以暂停生产，停止消耗原料。':'建筑会持续为家园带来帮助。'}</p><div class="action-row">${c.toggleable?`<button class="secondary" data-act="toggle" data-id="${c.id}">${c.enabled?'暂停生产':'恢复生产'}</button>`:''}<button class="danger" data-act="sell" data-id="${c.id}">拆除 1 座</button></div></div></details>`:''}`;}
function queueSection(c){return ({build:'buildings',research:'science',upgrade:'workshop'})[c.targetType||c.type];}
function queuePicture(c){const section=queueSection(c),card=vm[section]?.find(b=>b.id===(c.targetId||c.id))||c;return artFor(card,section);}
function queueCosts(c,kind,id){return `<div class="decision-costs" data-queue-costs="${kind}:${esc(id)}">${costMarkup(c)}</div>`;}
function queuePage(){
 const q=vm.queue||{items:[],options:[],used:0,capacity:3},pages=Math.max(1,Math.ceil(q.items.length/25));ui.queuePage=Math.min(Math.max(0,ui.queuePage),pages-1);const start=ui.queuePage*25;
 return heading('建造队列',`<button class="queue-back" data-nav="build" aria-label="返回建造">‹ 返回建造</button>`,'tabindex="-1" data-queue-heading')+`<section class="queue-panel"><div class="queue-overview"><b>按顺序完成</b><span><b data-queue-count>${fmt(q.used)}/${fmt(q.capacity)}</b> 已排队</span></div><p class="queue-rule" data-queue-rule>${q.paused?'已随游戏暂停':'物资齐备后自动完成 · 队首优先'}</p><ol class="queue-list">${q.items.slice(start,start+25).map((c,offset)=>`<li class="queue-item"><div class="queue-item-heading"><span class="queue-number">${start+offset+1}</span><span class="queue-picture">${queuePicture(c)}</span><h2>${esc(c.name)} <small>×${fmt(c.amount)}</small></h2></div><p class="queue-status" data-queue-status="${c.index??(start+offset)}">${esc(c.reason||c.status||'等待执行')}</p>${queueCosts(c,'item',c.index??(start+offset))}<div class="queue-controls"><button class="secondary" data-act="queueUp" data-id="${c.index??(start+offset)}" aria-label="上移${esc(c.name)}" ${start+offset===0?'disabled':''}>↑</button><button class="secondary" data-act="queueDown" data-id="${c.index??(start+offset)}" aria-label="下移${esc(c.name)}" ${start+offset===q.items.length-1?'disabled':''}>↓</button><button class="secondary" data-act="queueRemove" data-id="${c.index??(start+offset)}" aria-label="移除一项${esc(c.name)}">移除 1 项</button>${c.amount>1?`<button class="text-button" data-act="queueRemove" data-id="${c.index??(start+offset)}" data-amount="max" aria-label="移除整组${esc(c.name)}">移除整组</button>`:''}</div></li>`).join('')||`<li class="queue-empty">${image('buildings','hive')}<span>把想建的放进来<small>在下方排队，现在不扣物资</small></span></li>`}</ol>${pages>1?`<div class="queue-pagination" aria-label="队列翻页"><button class="secondary" data-queue-page="${ui.queuePage-1}" ${ui.queuePage===0?'disabled':''}>前 25 项</button><span>${ui.queuePage+1} / ${pages}</span><button class="secondary" data-queue-page="${ui.queuePage+1}" ${ui.queuePage===pages-1?'disabled':''}>后 25 项</button></div>`:''}${q.items.length?'<button class="queue-clear danger" data-act="queueClear" data-id="confirm">清空队列</button>':''}<h2 class="queue-choices-heading">添加到队列</h2><div class="queue-choices">${q.options.filter(c=>c.unlocked&&!c.completed).map(c=>`<article class="queue-choice"><span class="queue-picture">${queuePicture(c)}</span><h3>${esc(c.name)}</h3><button class="secondary" data-act="queueEnqueue" data-id="${esc(c.id)}" aria-label="将${esc(c.name)}加入队列" aria-disabled="${!c.available||!canAct()}">排队 ＋</button>${queueCosts(c,'option',c.id)}</article>`).join('')}</div></section>`;
}
function researchPage(){ui.researchFilterDirty=true;const sections=[['science','研究'],['workshop','技艺']].filter(([s])=>vm[s]?.some(known));if(!sections.some(([s])=>s===ui.researchTab))ui.researchTab=sections[0]?.[0]||'science';const section=ui.researchTab,cards=(vm[section]||[]).filter(known),fresh=cards.filter(c=>!c.completed),done=cards.filter(c=>c.completed);return heading('研究')+(sections.length>1?`<div class="segmented">${sections.map(([s,label])=>`<button data-research-tab="${s}" class="${s===section?'selected':''}" aria-pressed="${s===section}">${label}</button>`).join('')}</div>`:'')+`<details class="research-search-tools" ${ui.researchTools||ui.researchQuery||ui.researchReady?"open":""}><summary>查找与筛选 <span data-filter-summary>${ui.researchQuery||ui.researchReady?"筛选中":"全部研究"}</span></summary><div class="research-tools"><label>查找研究与收益<input type="search" id="research-search" placeholder="名称、解锁内容或收益" value="${esc(ui.researchQuery)}"></label><label class="filter-check"><input type="checkbox" id="research-ready" ${ui.researchReady?'checked':''}>只看可完成</label><button class="text-button" data-command="refresh-research">更新结果</button><button class="text-button" data-command="clear-research">清空筛选</button></div></details><div class="notebook-intro"><span>蜜林研究手册</span><small>目标会显示在每个页面</small></div><div class="research-list">${fresh.map(c=>card(c,section)).join('')}</div><p id="research-empty" class="detail-note" hidden>没有符合条件的项目，可清空搜索或关闭筛选。</p>`+(!fresh.length?empty('已经读完这一页，继续照料家园吧。'):'')+(done.length?`<details class="fold"><summary>已经掌握 · ${done.length}</summary><div class="research-list">${done.map(c=>card(c,section)).join('')}</div></details>`:'');}
function filterResearch(force=false){if(!force&&!ui.researchFilterDirty)return;writeText('[data-filter-summary]',ui.researchQuery||ui.researchReady?'筛选中':'全部研究');ui.researchFilterDirty=false;let visible=0;for(const node of app?.querySelectorAll('[data-research-card]')||[]){const [section,id]=node.dataset.researchCard.split(':'),c=vm[section]?.find(c=>c.id===id);node.hidden=!c||!researchMatches(c,ui.researchQuery,ui.researchReady);if(!node.hidden&&!c.completed)visible++;}const empty=app?.querySelector('#research-empty');if(empty)empty.hidden=visible>0;}
function researchInput(event){ui.researchTools=true;if(event.target.id==='research-search'){ui.researchQuery=event.target.value;filterResearch(true);}if(event.target.id==='research-ready'){ui.researchReady=event.target.checked;filterResearch(true);}}
function villagePage(){return heading('小熊')+`<div class="work-summary" role="status"><b>空闲 <span data-free-bears>${fmt(vm.bears.free)}</span> 只</b><span>口粮净产 <b data-food-net>${signed(getResource(vm,'honey').rate)}/秒</b></span></div><div class="village-overview">${image('bears','wave')}<div><h2>${fmt(vm.bears.value)} 只伙伴</h2><p>空闲 ${fmt(vm.bears.free)} · 住房 ${fmt(vm.bears.max)}</p><small>幸福感 ${fmt(vm.bears.happiness)}% · 每只基础口粮 ${fmt(vm.bears.foodPerBear||4.25,2)} 蜂蜜/秒</small><details class="happiness-detail"><summary>幸福感来源</summary>${(vm.bears.happinessBreakdown||[]).filter(x=>x.value).map(x=>`<p>${esc(x.label)} ${signed(x.value)}%</p>`).join('')}<p>幸福感最低为 25%；超过 100% 的工作状态也会增加口粮消耗。</p></details></div></div>${happinessAdvice()}`+(!vm.bears.value?empty('小屋已经准备好，留足蜂蜜，伙伴会慢慢搬进来。'):'')+`<div class="job-list">${vm.jobs.filter(known).map(c=>`<article class="job-card" tabindex="-1" data-job-card="${c.id}"><button class="job-portrait" data-detail="jobs:${c.id}" aria-label="${esc(c.name)}工作详情">${image('workers',c.id,'','ready')}</button><div><h2>${esc(c.name)}</h2><p class="job-contribution">当前合计 <b data-job-rate="${c.id}">${signed(c.currentRate||0)}</b> ${esc(getResource(vm,c.output).name)}/秒</p><p data-job-preview="${c.id}">${jobPreview(c)}</p></div><div class="job-stepper"><button data-act="unassign" data-id="${c.id}" aria-label="减少一只${esc(c.name)}">−</button><b data-assigned="${c.id}">${fmt(c.assigned)}</b><button data-act="assign" data-id="${c.id}" aria-label="增加一只${esc(c.name)}">＋</button><button class="text-button" data-act="assign" data-id="${c.id}" data-amount="max">分配全部空闲</button><button class="text-button" data-transfer-to="${c.id}">从其他岗位调来</button></div><div class="action-error" data-action-error="jobs:${c.id}" role="status" hidden></div></article>`).join('')}</div>`+(vm.actions.some(c=>c.type==='hunt'&&c.unlocked)?`<div class="page-body" data-hunt-section tabindex="-1"><h2>去林间走走</h2><p class="detail-note">消耗 100 活力，寻找毛皮和象牙。</p><div class="action-row"><button class="primary" data-act="hunt" data-id="hunt">巡林 1 次</button><button class="secondary" data-act="hunt" data-id="hunt" data-amount="max">批量巡林</button></div></div>`:'');}
function jobPreview(c){return c.nextRate==null?'没有空闲伙伴；可先从其他岗位撤回一只。':`再加 1 只：${signed(c.nextRate)} ${getResource(vm,c.output).name}/秒${c.nextFood<0?'，口粮额外 '+fmt(-c.nextFood,2)+'/秒':''}`;}
function craftsPage(){return heading('林间工坊',`<button data-nav="more">返回更多</button>`)+`<div class="craft-list">${vm.crafts.filter(known).map(c=>card(c,'crafts')).join('')}</div>`;}
function morePage(){const craft=vm.crafts.some(c=>c.id!=='wood'&&known(c));return heading('更多')+`<div class="more-summary"><button data-command="resources">库存与收支</button><button data-nav="build/queue">建造队列 <b data-queue-count>${fmt(vm.queue?.used||0)}/${fmt(vm.queue?.capacity||3)}</b></button><button data-command="notifications">重要消息 ${fmt((settings.notices||[]).filter(n=>!n.read).length)}</button><button data-command="chapter-progress">成长路线</button></div><div class="more-list">${vm.science.some(known)?`<button data-nav="research">${image('resources','science')}<span>林间研究</span>${icon('arrow')}</button>`:''}${vm.bears.max>0||vm.bears.value>0?`<button data-nav="village">${image('bears','wave')}<span>小熊与工作</span>${icon('arrow')}</button>`:''}${craft?`<button data-nav="crafts">${image('buildings','workshop')}<span>林间工坊</span>${icon('arrow')}</button>`:''}<button data-command="journal">${icon('leaf')}<span>林间手记</span>${icon('arrow')}</button><button data-command="settings">${icon('settings')}<span>设置</span>${icon('arrow')}</button><button data-command="saves">${icon('save')}<span>存档与备份</span>${icon('arrow')}</button><button data-command="help">${icon('help')}<span>游戏说明</span>${icon('arrow')}</button></div><p class="save-foot">第一章 · 林间家园<br><span id="save-label">进度保存在此设备</span></p>`;}
function mapPage(){return heading('森林地图',`<button data-nav="home">回到家园</button>`)+`<div class="world-map-scroll" tabindex="0" aria-label="可上下滚动的森林地图">${visibleRegions(vm).map(r=>{const {buildings,height}=sceneLayout(vm,r.id),previewHeight=Math.min(320,height*.36),scale=previewHeight/height;return `<button class="map-region" data-region="${r.id}" aria-label="进入${r.name}，${buildings.length}类建筑" style="background-image:url('${esc(art.scenery?.background||art.background)}')"><span class="region-buildings" style="height:${previewHeight}px" aria-hidden="true">${buildings.map(({card:c,x,y})=>`<span class="map-building" data-map-building="${c.id}" style="--x:${x}%;--y:${y/height*100}%;height:${176*scale}px">${buildingImage(c)}</span>`).join('')}</span><b>${r.name}</b><small>${buildings.length?'已有 '+buildings.length+' 类建筑':'一片安静的林间空地'}</small></button>`;}).join('')}</div>`;}

function updateViewLayout(){const shell=app?.querySelector('.app-shell');shell?.classList.toggle('home-view',ui.page==='home');shell?.classList.toggle('map-view',ui.page==='map');shell?.classList.toggle('build-view',ui.page==='build');shell?.classList.toggle('map-collapsed',!!settings.mapCollapsed);shell?.classList.toggle('management-view',!['home','map'].includes(ui.page));}
function render(force=false){if(!game||!app)return;vm=game.snapshot();updateViewLayout();if(ui.page==='home')normalizeHomeRegion();renderStatus();collectNotices(vm);hud();nav();updateTarget();const key=pageKey(),structure=structuralKey(),main=app.querySelector('#main-content');const reading=['research','village','crafts'].includes(ui.page)&&ui.pageKey===key&&!force;if(reading&&ui.structureKey!==structure){const head=main.querySelector('.page-heading');if(head&&!head.querySelector('[data-command="refresh-research"]'))head.insertAdjacentHTML('beforeend','<button class="refresh-notice" data-command="refresh-research">有新内容 · 更新</button>');}if(force||ui.pageKey!==key||ui.page!=='home'&&ui.structureKey!==structure&&!reading){const focus=activeKey();const pageScroll=main.scrollTop,windowScroll=window.scrollY;const picker=main.querySelector('.building-picker')?.scrollLeft||0;const open=[...main.querySelectorAll('details[open]')].map(d=>d.querySelector('summary')?.textContent);if(ui.page==='home'&&main.querySelector('.world-board')&&ui.pageKey?.startsWith('home:')){ui.scrolls[ui.pageKey]=main.querySelector('.world-scene').scrollTop;}main.innerHTML=({home,build:buildPage,research:researchPage,village:villagePage,more:morePage,map:mapPage,crafts:craftsPage,queue:queuePage}[ui.page]||home)();if(ui.page==='home')main.querySelector('.world-scene').scrollTop=ui.scrolls[pageKey()]||0;for(const d of main.querySelectorAll('details'))if(open.includes(d.querySelector('summary')?.textContent))d.open=true;if(main.querySelector('.building-picker'))main.querySelector('.building-picker').scrollLeft=picker;main.scrollTop=pageScroll;if(ui.pageKey===key)window.scrollTo({top:windowScroll,behavior:'instant'});restoreFocus(focus);ui.pageKey=pageKey();}if(!reading)ui.structureKey=structure;if(ui.page==='research')filterResearch();if(ui.page==='home')updateScene();updateLive();ui.queueKey=queueOrderKey(vm);}
function findCard(type,id,section){if(type==='queueEnqueue')return vm.queue?.options?.find(c=>c.id===id);if(['queueUp','queueDown','queueRemove'].includes(type))return vm.queue?.items?.find(c=>String(c.index)===String(id));if(type==='queueClear')return vm.queue;if(section&&vm[section])return vm[section].find(c=>c.id===id);if(['build','sell','toggle'].includes(type))return vm.buildings.find(c=>c.id===id);if(['assign','unassign'].includes(type))return vm.jobs.find(c=>c.id===id);if(type==='research')return vm.science.find(c=>c.id===id);if(type==='upgrade')return vm.workshop.find(c=>c.id===id);return vm.actions.find(c=>c.id===id&&c.type===type)||vm.crafts.find(c=>c.id===id);}
function allowed(type,c){if(!canAct())return false;if(type==='queueClear')return !!c?.items?.length;if(type==='queueRemove')return c?.amount>0;if(type==='queueUp')return c?.index>0;if(type==='queueDown')return c?.index<((vm.queue?.items?.length||0)-1);if(type==='sell')return c?.owned>0;if(type==='toggle')return c?.owned>0&&c.toggleable;if(type==='unassign')return c?.assigned>0;return c?.available===true;}
function updateLive(){for(const el of app?.querySelectorAll?.('[data-card-state]')||[]){const [section,id]=el.dataset.cardState.split(':');const c=vm[section]?.find(c=>c.id===id);if(c){const state=decisionState(c,vm);el.textContent=state.label;el.className='decision-state '+state.kind;}}writeText('[data-free-bears]',fmt(vm.bears.free));writeText('[data-food-net]',signed(getResource(vm,'honey').rate)+'/秒');for(const el of app?.querySelectorAll?.('[data-build-state]')||[]){const c=vm.buildings.find(c=>c.id===el.dataset.buildState);if(c){const state=decisionState(c,vm);el.textContent=state.label;el.className='decision-state '+state.kind;}}for(const el of document.querySelectorAll('[data-queue-count]'))el.textContent=`${fmt(vm.queue?.used||0)}/${fmt(vm.queue?.capacity||3)}`;writeText('[data-queue-rule]',vm.queue?.paused?'已随游戏暂停':'物资齐备后自动完成 · 队首优先');for(const el of document.querySelectorAll('[data-queue-costs]')){const [kind,...parts]=el.dataset.queueCosts.split(':'),id=parts.join(':'),c=kind==='item'?vm.queue?.items?.find(c=>String(c.index)===id):vm.queue?.options?.find(c=>c.id===id);if(c){const html=costMarkup(c);if(el.innerHTML!==html)el.innerHTML=html;}}for(const el of document.querySelectorAll('[data-queue-status]')){const c=vm.queue?.items?.find(c=>String(c.index)===el.dataset.queueStatus);if(c)el.textContent=c.reason||c.status||'等待执行';}for(const el of document.querySelectorAll('[data-costs]')){const [section,id]=el.dataset.costs.split(':');const c=vm[section]?.find(c=>c.id===id);if(c){const html=costMarkup(c);if(el.innerHTML!==html)el.innerHTML=html;}}for(const el of document.querySelectorAll('[data-act]')){const c=findCard(el.dataset.act,el.dataset.id,el.dataset.section);const amount=Number(el.dataset.amount)||1,yes=allowed(el.dataset.act,c)&&(amount<=1||!['build','craft','refine','hunt'].includes(el.dataset.act)||batchPreview(c,amount,vm).affordable);el.setAttribute('aria-disabled',String(!yes));}for(const c of vm.jobs||[])for(const el of document.querySelectorAll(`[data-assigned="${c.id}"]`))el.textContent=fmt(c.assigned);for(const c of vm.jobs||[]){writeText(`[data-job-rate="${c.id}"]`,signed(c.currentRate||0));writeText(`[data-job-preview="${c.id}"]`,jobPreview(c));}writeText('#save-label',storageIssue||loadBlocked?'存档需要检查':vm.saveStatus?.at?'刚刚已保存':'进度保存在此设备');for(const node of document.querySelectorAll('[data-building-outcome]')){const c=vm.buildings.find(c=>c.id===node.dataset.buildingOutcome);if(c){const value=buildingOutcome(c);if(node.textContent!==value)node.textContent=value;}}if(dialog?.kind==='resources')updateInventory();if(dialog?.kind==='transfer')updateTransferPreview();renderErrors();}
function pageScrollKey(){return ui.page==='research'?'research:'+ui.researchTab:ui.page==='queue'?'queue:'+ui.queuePage:ui.page;}
function navigationContext(){return {page:ui.page,region:ui.region,buildChoice:ui.buildChoice,researchTab:ui.researchTab,researchQuery:ui.researchQuery,researchReady:ui.researchReady,queuePage:ui.queuePage,scroll:globalThis.window?.scrollY||0,dialog:dialog?.kind==='resources'?{...dialog}:null,label:dialog?.kind==='resources'?'库存':({home:'家园目标',build:'建造目标',research:'研究目标',village:'工作安排',crafts:'制作目标',more:'更多'}[ui.page]||'原目标')};}
function rememberPage(){rememberScene();ui.pageScrolls[pageScrollKey()]=globalThis.window?.scrollY||0;}
function restorePage(){globalThis.window?.scrollTo?.({top:ui.pageScrolls[pageScrollKey()]||0,behavior:'instant'});if(ui.pendingTarget){const target=ui.pendingTarget;ui.pendingTarget=null;const node=app?.querySelector(target);if(node){node.hidden=false;node.classList.add('decision-focus');node.scrollIntoView?.({block:'center',behavior:'instant'});node.focus?.({preventScroll:true});setTimeout(()=>node.classList?.remove('decision-focus'),2500);}}}
function returnToTask(){const context=ui.returnContext;if(!context)return;rememberPage();ui.returnContext=null;ui.pendingTarget=null;Object.assign(ui,{page:context.page,region:context.region,buildChoice:context.buildChoice,researchTab:context.researchTab,researchQuery:context.researchQuery,researchReady:context.researchReady,queuePage:context.queuePage});ui.pageScrolls[pageScrollKey()]=context.scroll;const hash=context.page==='home'?'home/'+context.region:context.page==='queue'?'build/queue':context.page;closeDialog(true);history.pushState({},'','#'+hash);readHash();render(true);restorePage();if(context.dialog)openDialog('resources','森林仓库',{resource:context.dialog.resource});}
function syncSceneFocus(){const scene=app?.querySelector('.world-scene');if(!scene?.getBoundingClientRect)return;const bounds=scene.getBoundingClientRect();for(const el of scene.querySelectorAll('button')){const rect=el.getBoundingClientRect();el.tabIndex=!settings.mapCollapsed&&rect.bottom>bounds.top+8&&rect.top<bounds.bottom-8?0:-1;}}
function rememberScene(){const scene=app.querySelector('.world-scene');if(scene)ui.scrolls[pageKey()]=scene.scrollTop;}
function normalizeHomeRegion(){
 if(!visibleRegions(vm).some(r=>r.id===ui.region))ui.region='village';
 const [page,region]=location.hash.slice(1).split('/');
 if(page==='home'&&region&&region!=='map'&&region!==ui.region)history.replaceState(history.state,'','#home/'+ui.region);
}
function readHash(){const [page,region]=location.hash.slice(1).split('/');ui.page=['home','build','research','village','more','map','crafts'].includes(page)?page:'home';if(ui.page==='build'&&region==='queue')ui.page='queue';if(ui.page==='home'&&region==='map')ui.page='map';else if(ui.page==='home'){ui.region=region||ui.region;normalizeHomeRegion();}if(ui.page==='crafts'&&!vm.crafts.some(known))ui.page='more';if(ui.page==='research'&&!vm.science.some(known))ui.page='home';}
function navigate(page,region){rememberPage();ui.navigating=true;if(page==='home'&&!region&&ui.revealBuilding)region=visibleRegions(vm).find(r=>r.buildings.includes(ui.revealBuilding))?.id;const hadDialogHistory=dialogHistory;closeDialog(true);const hash=page==='home'?'home/'+(region||ui.region):page;if(hadDialogHistory){const state={...history.state};delete state.forestDialog;history.replaceState(state,'','#'+hash);readHash();render(true);restorePage();ui.navigating=false;return;}if(location.hash==='#'+hash){readHash();render(true);restorePage();ui.navigating=false;}else location.hash=hash;}
function dialogBody(){if(!dialog)return '';const c=dialog.section?vm[dialog.section]?.find(c=>c.id===dialog.id):null;switch(dialog.kind){case 'detail':if(!c||!known(c))return '<p>这个发现还没有出现在森林里。</p>';return `<div class="detail-hero">${dialog.section==='jobs'?image('workers',c.id):artFor(c,dialog.section)}</div><h2>${esc(c.name)}</h2><p>${esc(c.description)}</p>${forestBenefits(c,dialog.section,vm)?`<div class="detail-effect">${esc(forestBenefits(c,dialog.section,vm))}</div>`:''}${dialog.section==='jobs'?`<p>已分配 ${fmt(c.assigned)} 只伙伴</p><button class="primary" data-nav="village">安排工作</button>`:costs(c,dialog.section)+actionButtons(c,dialog.section)}${['buildings','crafts'].includes(dialog.section)&&!c.completed?'<p class="detail-note">可选择最大数量；批量操作前会显示消耗与剩余供你确认。</p>':''}${dialog.section==='buildings'&&c.owned?`<div class="action-row">${c.toggleable?`<button class="secondary" data-act="toggle" data-id="${c.id}">${c.enabled?'暂停生产':'恢复生产'}</button>`:''}<button class="danger" data-act="sell" data-id="${c.id}">拆除 1 座</button></div>`:''}`;
 case 'bear':{const b=vm.bears.individuals.find(b=>String(b.id)===dialog.id);if(!b)return '<p>伙伴正在林间走动。</p>';return `<div class="detail-hero">${image('workers',b.job||'idle')||image('bears','idleFront')}</div><h2>${esc(b.name||'小熊')}</h2><p>${esc(stopped()?'我在这里，等你准备好再继续。':bearLines[b.job]||bearLines.idle)}</p><button class="primary" data-nav="village">看看伙伴的工作</button>`;}
 case 'resources':return `<p class="detail-note">净产已扣除消耗；展开一项查看来源。蜂蜜始终保留；另有 2 个固定位置，已用 ${(settings.pinned||[]).filter(id=>id!=='honey').length}/2。位置满时可选择替换哪项。</p><div id="inventory">${vm.resources.filter(r=>r.visible).map(r=>`<details class="inventory-item ${dialog.resource===r.id?'highlighted':''}" data-inventory="${r.id}" ${dialog.resource===r.id?'open':''}><summary>${image('resources',r.id)}<b>${esc(r.name)}</b><span class="inventory-number"><b data-stock="${r.id}">${fmt(r.value,1)}</b><small>${r.max==null?'不限容量':'/ '+fmt(r.max)}</small><small data-stock-rate="${r.id}">${rates(r)}</small></span></summary><div class="inventory-detail"><p>${esc(r.description||'')}</p>${r.id==='honey'?'<p class="permanent-pin">蜂蜜始终显示在顶部</p>':`<button class="text-button" data-pin="${r.id}" aria-pressed="${(settings.pinned||[]).includes(r.id)}">${(settings.pinned||[]).includes(r.id)?'取消固定':'固定关注'}</button>`}${acquisition(r)}${r.max!=null?`<progress max="${r.max}" value="${r.value}" data-stock-progress="${r.id}" aria-label="${esc(r.name)}库存容量"></progress>`:''}<p data-horizon="${r.id}">${stopped()?'恢复后按当前速率预计：':''}${resourceHorizon(r)}</p><div class="income-lines"><span>总产出 <b data-gross="${r.id}">${signed(r.grossRate||0)}/秒</b></span><span>总消耗 <b data-consumption="${r.id}">${signed(-(r.consumptionRate||0))}/秒</b></span></div><div class="resource-sources" data-resource-sources="${r.id}">${(r.breakdown||[]).map(x=>`<p><span>${esc(x.label)}</span><b>${signed(x.rate)}/秒</b></p>`).join('')||'<p>暂无持续收支。</p>'}</div></div></details>`).join('')}</div>`;
 case 'settings':return `<button class="setting-row" data-command="pause"><span><b>暂停游戏</b><small>暂停期间，生产和日历都停下来。</small></span><span class="setting-value">${vm.settings.paused?'已暂停':'生长中'}</span></button><button class="setting-row" data-command="offline"><span><b>离线生长</b><small>关闭页面后继续计算，最多结算 ${fmt(constants.MAX_OFFLINE_SECONDS/3600,2)} 小时。小熊仍会消耗蜂蜜。</small></span><span class="setting-value">${vm.settings.offline?'已开启':'已关闭'}</span></button><button class="setting-row" data-command="motion"><span><b>减少动态效果</b><small>让工作姿势和加载小熊保持安静。</small></span><span class="setting-value">${settings.reducedMotion?'已开启':'已关闭'}</span></button><button class="setting-row" data-command="text-size" aria-pressed="${settings.textSize==='large'}"><span><b>文字大小</b><small>切换标准与大字号，选择会保存在此浏览器。</small></span><span class="setting-value">${settings.textSize==='large'?'大字号':'标准'}</span></button><div class="save-actions"><button class="secondary" data-command="saves">存档与备份</button></div>`;
 case 'saves':return `<p>进度只保存在当前浏览器。换设备前，先导出一份存档。</p>${storageIssue||loadBlocked?`<p class="negative">${esc(storageIssue||vm.saveStatus?.message||'存档无法读取，原始数据已保留。')}</p>`:''}${settlementFailed?`<p class="negative">${esc(settlementFailureMessage)}</p><p>当前推进已停止，已保存的原始存档不会被覆盖。请先下载备份，再重新加载重试；不会跳过尚未结算的时间。</p>`:''}<div class="save-actions">${!settlementFailed?'<button class="primary" data-command="save">保存当前进度</button>':''}${!loadBlocked&&!vm.pendingOffline?'<button class="secondary" data-command="export">导出当前存档</button>':''}${readStorage(constants.SAVE_KEY)!==null?'<button class="secondary" data-command="backup-slot">下载已保存的原始存档</button>':''}${readStorage(LEGACY_KEY)!==null?'<button class="secondary" data-command="legacy">下载旧存档原始备份</button>':''}${settlementFailed?'<button class="primary" data-command="reload">重新加载</button>':''}<button class="secondary" data-command="import">导入存档文件</button></div><p class="detail-note">导入前会检查存档兼容性，再由你确认替换。旧存档使用独立位置，本章不会改写它。</p>`;
 case 'help':return `<div class="help-content">${image('bears','wave')}<h2>一点点，长成家园</h2><h3>从蜂蜜和木头开始</h3><p>在家园采集蜂蜜，再用蜂蜜采木。蜂箱会持续生产蜂蜜；小屋建好后，伙伴会陆续搬进来。</p><h3>让每只小熊都有一份工作</h3><p>在小熊页分配采蜜、伐木和研究等工作。顶部显示净产量，已经扣除了伙伴的口粮与生产消耗。冬天蜂蜜较少，提前留粮。</p><h3>读书，也动手</h3><p>书屋扩大知识容量，研究带来新的建筑。工坊开放木梁和石板制作，技艺能让日常工作更顺利。</p><h3>先排队，慢慢建</h3><p>建造页右上角可以打开建造队列。把已经发现的建筑、研究或技艺排好顺序，物资齐备后就会自动完成。队首优先，暂停游戏时队列也会暂停。</p><h3>地图和建筑</h3><p>家园地图可以上下滑动。地图与家园使用同一组区域；点建筑看成本、效果和管理选项，点小熊听一句林间闲话。</p><h3>第一章的心愿</h3><p>掌握营造技术，建好木屋、仓库和伐木场，林间家园就长成了。完成后仍能继续游玩。</p><h3>把家园收好</h3><p>游戏自动保存。更多中可以暂停、管理离线生长、导出备份。批量制作和拆除都会先询问你。</p></div>`;
 case 'chapter-progress':return stageMarkup();
 case 'transfer':return transferBody();
 case 'pin-replace':return `<p>两个固定位置已用满。请选择要替换的资源，蜂蜜会继续保留。</p><div class="save-actions">${(settings.pinned||[]).map(id=>`<button class="secondary" data-pin-replace="${id}">用${esc(getResource(vm,dialog.resource).name)}替换${esc(getResource(vm,id).name)}</button>`).join('')}</div>`;
 case 'target':return `<h2>${esc(c?.name||'当前项目')}</h2><p>目标会保持在所有页面，补充物资后可直接返回。</p><label class="target-quantity">${dialog.section==='buildings'?'从现在起再建造':'从现在起制作'}<input id="target-amount" type="number" inputmode="numeric" min="1" max="1000000" value="1">${dialog.section==='buildings'?'座':'次'}</label><button class="primary" data-command="confirm-target">固定目标</button>`;
 case 'completion':return `<div class="detail-hero">${image('bears','wave')}</div><h2>林间家园长成了</h2><p>营造技术读懂了，木屋、仓库和伐木场，也都有了自己的位置。</p><p>这是一段慢慢积攒的林间时光。和小熊一起，继续照料这片森林吧。</p><button class="primary" data-command="close">继续照料家园</button>`;
 case 'calendar':return `<h2>第 ${fmt(vm.calendar.year)} 年 · ${esc(vm.calendar.seasonName)} ${fmt(vm.calendar.day)} 天</h2><p>${esc(vm.calendar.weatherName||'天气平和')}。蜂箱受季节和天气影响，养蜂熊不受季节影响。</p><p>${stopped()?'恢复后距下一季约':'距下一季约'} ${duration(((constants.DAYS_PER_SEASON-vm.calendar.day)*constants.TICKS_PER_DAY-vm.calendar.tick)/constants.TICKS_PER_SECOND)}。</p><p>给冬天留一点余粮：安排采蜜熊，添置蜂箱和储存建筑，让伙伴们安心过冬。</p>`;
 case 'notifications':return `<p class="detail-note">入住、研究、缺粮和区域变化会保留在这里，最多保留 20 条。</p><button class="secondary" data-command="read-notices">全部标为已读</button><div class="notice-list">${noticeGroups().map(group=>`<section class="notice-group"><h3>${group.title} · ${group.items.length}</h3>${group.items.map(n=>`<article class="notice-item ${n.read?'':'unread'}"><p>${esc(n.text)}</p>${n.region?`<button class="text-button" data-region="${esc(n.region)}">前往山边工坊 ›</button>`:n.page?`<button class="text-button" data-nav="${esc(n.page)}">前往处理 ›</button>`:n.command?`<button class="text-button" data-command="${esc(n.command)}">查看收获 ›</button>`:''}</article>`).join('')}</section>`).join('')||'<p>暂时没有新的重要消息。</p>'}</div>`;
 case 'journal':return vm.log.map(l=>`<p>${esc(l.text)}</p>`).join('')||'<p>森林的故事，才刚刚开始。</p>';
 case 'confirm':return `<h2>${esc(dialog.heading)}</h2><p class="confirm-copy">${esc(dialog.text)}</p>${dialog.preview?previewMarkup(dialog.preview):''}<div class="action-row"><button class="secondary" data-command="cancel">先不操作</button><button class="${dialog.destructive?'danger':'primary'}" data-command="confirm">确认继续</button></div>`;
 case 'offline':{const report=vm.offlineReport||{},changes=Object.entries(report.resources||{});return `<div class="offline-body">${image('bears','idleFront')}<h2>欢迎回到蜜林</h2><p>离开了 ${fmt((report.seconds||0)/60,1)} 分钟</p></div>${[['收获',changes.filter(([,value])=>value>.01)],['消耗',changes.filter(([,value])=>value<-.01)]].filter(([,rows])=>rows.length).map(([title,rows])=>`<section class="offline-group"><h3>${title}</h3>${rows.map(([id,value])=>`<p>${esc(getResource(vm,id).name)} <b class="${value<0?'negative':''}">${signed(value)}</b></p>`).join('')}</section>`).join('')||'<p>这段时间没有明显的物资变化。</p>'}${report.bears?`<section class="offline-group"><h3>伙伴变化</h3><p>${report.bears>0?'新入住':'离开'} ${fmt(Math.abs(report.bears))} 只伙伴</p></section>`:''}${getResource(vm,'honey').rate<0?'<div class="happiness-advice"><p>当前口粮净产为负，继续照料前可先调整分工。</p><button class="secondary" data-command="food-help">处理口粮</button></div>':''}<button class="primary" data-command="close">继续照料森林</button>`;}

 case 'settling':return `<div class="offline-body">${image('bears','idleFront')}<h2>正在整理林间收获</h2><p>按实际规则计算离开的时间。请稍候，完成后就能继续。</p><progress class="offline-progress" value="0" max="1" aria-label="离线结算进度"></progress><span id="offline-label">0%</span></div>`;
 default:return '';}}
function openDialog(kind,title,data={}){if(settling&&kind!=='settling')return;if(!dialog){returnFocus=document.activeElement;if(kind!=='settling'&&kind!=='offline'){history.pushState({...history.state,forestDialog:true},'');dialogHistory=true;}}if(kind==='confirm'&&dialog&&dialog.kind!=='confirm')parentDialog={...dialog};else if(kind!=='confirm')parentDialog=null;dialog={kind,title,...data};refreshDialog(true);}
function refreshDialog(focus=false){if(!dialog)return;const oldScroll=dialogRoot.querySelector('.dialog-body')?.scrollTop||0;const focusKey=activeKey();const expanded=[...dialogRoot.querySelectorAll('[data-inventory][open]')].map(el=>el.dataset.inventory);dialogRoot.innerHTML=`<div class="dialog-backdrop"><section class="dialog" tabindex="-1" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="dialog-header"><h2 id="dialog-title">${esc(dialog.title)}</h2>${dialog.kind==='settling'?'':`<button class="icon-button" data-command="close" aria-label="关闭弹窗">${icon('close')}</button>`}</header><div class="dialog-body">${dialogBody()}</div></section></div>`;for(const id of expanded){const node=dialogRoot.querySelector(`[data-inventory="${id}"]`);if(node)node.open=true;}app.inert=true;document.body.classList.add('modal-open');dialogRoot.querySelector('.dialog-body').scrollTop=oldScroll;updateLive();if(focus&&dialog.kind==='resources'&&dialog.resource)dialogRoot.querySelector(`[data-inventory="${dialog.resource}"]`)?.scrollIntoView?.({block:'start'});if(focus)(dialogRoot.querySelector('[data-command="close"]')||dialogRoot.querySelector('.dialog')).focus({preventScroll:true});else restoreFocus(focusKey);}
function closeDialog(fromHistory=false){if(!dialog||settling)return;const back=dialogHistory&&!fromHistory;dialog=null;parentDialog=null;dialogHistory=false;dialogRoot.innerHTML='';app.inert=false;document.body.classList.remove('modal-open');returnFocus?.isConnected?returnFocus.focus({preventScroll:true}):app.querySelector('#main-content')?.focus({preventScroll:true});returnFocus=null;if(back)history.back();}
function cancelDialog(){if(parentDialog){dialog=parentDialog;parentDialog=null;refreshDialog(true);}else closeDialog();}
function confirmAction(heading,text,confirm,destructive=false){openDialog('confirm','请确认',{heading,text,confirm,destructive});}
function updateInventory(){for(const r of vm.resources){writeText(`[data-stock="${r.id}"]`,fmt(r.value,1),dialogRoot);writeText(`[data-stock-rate="${r.id}"]`,rates(r),dialogRoot);writeText(`[data-horizon="${r.id}"]`,(stopped()?'恢复后按当前速率预计：':'')+resourceHorizon(r),dialogRoot);writeText(`[data-gross="${r.id}"]`,signed(r.grossRate||0)+'/秒',dialogRoot);writeText(`[data-consumption="${r.id}"]`,signed(-(r.consumptionRate||0))+'/秒',dialogRoot);const sources=dialogRoot.querySelector(`[data-resource-sources="${r.id}"]`);if(sources){const markup=(r.breakdown||[]).map(x=>`<p><span>${esc(x.label)}</span><b>${signed(x.rate)}/秒</b></p>`).join('')||'<p>暂无持续收支。</p>';if(sources.innerHTML!==markup)sources.innerHTML=markup;}const meter=dialogRoot.querySelector(`[data-stock-progress="${r.id}"]`);if(meter)meter.value=r.value;}}
function perform(type,id,amount=1,origin=null){if(!canAct()){notify(storageIssue||loadBlocked?'请先检查并备份存档。':readOnly?'另一页正在照料森林，请先选择在此页继续。':'请等当前结算完成。');return {ok:false};}const result=game.act(type,id,amount);vm=game.snapshot();if(result.ok!==false){for(const [key,error] of Object.entries(ui.actionErrors))if(error.id===id)delete ui.actionErrors[key];if(['craft','refine'].includes(type)&&settings.tracked?.section==='crafts'&&settings.tracked.id===id){settings.tracked.produced=(settings.tracked.produced||0)+(Number(amount)||1);persistUI();}if(type==='build')ui.revealBuilding=id;save();render(ui.page!=='home');if(dialog?.kind==='detail')refreshDialog();if(type!=='gather'&&type!=='refine'||amount!==1)notify(result.message||'已经完成。');else if(type==='refine')notify(result.message||'木头已经收好了。',1600);}else{if(origin)actionError(origin,result.message||'还需要准备一点物资。');notify(result.message||'还需要准备一点物资。');}return result;}
function requestAction(button){const {act:type,id,section}=button.dataset,amount=button.dataset.amount==='max'?'max':Math.max(1,Number(button.dataset.amount)||1);const c=findCard(type,id,section);if(!allowed(type,c)){const message=!canAct()?'当前暂停操作，请查看顶部提示。':c?.reason||'还需要准备一点物资。';actionError(button,message);notify(message);return;}if(type==='queueClear'){confirmAction('清空建造队列？','移除所有尚未完成的排队项目。已经完成的建筑与研究会保留。',()=>{closeDialog();perform('queueClear','confirm');},true);return;}if(type==='queueRemove'){perform(type,id,amount);return;}if(type==='sell'){confirmAction(`拆除一座${c.name}？`,'这会失去这座建筑的作用，并返还部分物资。住房减少可能影响伙伴，仓库减少可能损失超出容量的物资。此操作无法撤销。',()=>{closeDialog();perform(type,id,1);},true);return;}if((amount==='max'||amount>1)&&!['assign','unassign'].includes(type)){const preview=batchPreview(c,amount,vm);if(!preview.affordable){actionError(button,'批量操作物资不足，请减少数量或补充物资。');notify('批量操作物资不足，请减少数量或继续积攒。');return;}confirmAction('确认批量操作？',`${c.name} · ${fmt(preview.count)} 次${type==='build'?'，价格已按逐座递增计算。':'，请检查以下消耗与剩余。'}`,()=>{closeDialog();perform(type,id,preview.count,button);});dialog.preview=preview;refreshDialog(true);return;}perform(type,id,amount,button);}
function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function backup(key,name){const text=readStorage(key);if(text===null){notify('没有找到可下载的存档。');return;}download(text,name);notify('已准备原始存档下载，内容未作修改。');}
function exportSave(){if(loadBlocked){backup(constants.SAVE_KEY,'Beargame-存档原始备份.json');return;}try{download(game.exportSave(),`Beargame-林间存档-${new Date().toISOString().slice(0,10)}.json`);notify('已准备存档下载，请妥善保存。');}catch(e){notify('无法导出：'+e.message,6000);}}
function toggleSetting(key){if(!canAct()){notify('当前页面不能更改游戏节奏。');return;}flushActive();if(!canAct())return;game.setSetting(key,!game.snapshot().settings[key]);lastTick=now();save();render();refreshDialog();}
async function command(name){switch(name){case 'return-task':returnToTask();break;case 'focus-hunt':app.querySelector('[data-hunt-section]')?.scrollIntoView({block:'center'});app.querySelector('[data-hunt-section]')?.focus({preventScroll:true});break;case 'confirm-transfer':{if(!canAct())return;const preview=game.previewTransfer(dialog.from,dialog.id,dialog.amount??1);if(!preview.ok){updateTransferPreview();return;}const result=game.act('reassign',dialog.from+':'+dialog.id,dialog.amount??1);if(result.ok){save();closeDialog();render(true);notify(result.message);}else{updateTransferPreview();notify(result.message);}break;}case 'open-target':openTarget();break;case 'clear-target':settings.tracked=null;persistUI();render(true);break;case 'confirm-target':{const amount=dialogRoot.querySelector('#target-amount')?.value||1;settings.tracked=createTrackedGoal(vm,dialog.section,dialog.id,amount);persistUI();closeDialog();render(true);notify('已固定当前目标，可在各页查看进度。');break;}case 'chapter-progress':openDialog('chapter-progress','第一章 · 成长路线');break;case 'map-toggle':settings.mapCollapsed=!settings.mapCollapsed;persistUI();render(true);break;case 'clear-research':ui.researchQuery='';ui.researchReady=false;ui.researchTools=false;render(true);break;case 'retry-art':notify('正在重新载入插画。');prefetchArt(true);break;case 'notifications':openDialog('notifications','重要消息');break;case 'read-notices':settings.notices=(settings.notices||[]).map(n=>({...n,read:true}));persistUI();writeText('[data-notice-count]','消息');refreshDialog();break;case 'food-help':{const farmer=vm.jobs.find(j=>j.id==='farmer');ui.returnContext=navigationContext();ui.buildChoice='hive';if(farmer?.unlocked)ui.pendingTarget='[data-job-card="farmer"]';navigate(farmer?.unlocked?'village':'build');break;}case 'resources':openDialog('resources','森林仓库');break;case 'refresh-research':render(true);filterResearch();break;case 'settings':openDialog('settings','照料森林的节奏');break;case 'saves':openDialog('saves','存档与备份');break;case 'help':openDialog('help','关于蜜林');break;case 'journal':openDialog('journal','林间手记');break;case 'calendar':openDialog('calendar','林间日历');break;case 'completion':openDialog('completion','第一章 · 家园长成了');break;case 'close':dialog?.kind==='confirm'?cancelDialog():closeDialog();break;case 'cancel':cancelDialog();break;case 'confirm':dialog?.confirm?.();break;case 'pause':toggleSetting('paused');break;case 'offline':toggleSetting('offline');break;case 'text-size':settings.textSize=settings.textSize==='large'?'normal':'large';applyTextSize();persistUI();render(true);refreshDialog();break;case 'motion':settings.reducedMotion=!settings.reducedMotion;writeStorage(UI_KEY,JSON.stringify(settings));document.documentElement.classList.toggle('motion-reduced',settings.reducedMotion);renderStatus();refreshDialog();break;case 'save':{const r=save();notify(r.message||(r.ok?'森林已经好好保存。':'保存失败，请导出备份。'));render();break;}case 'export':exportSave();break;case 'legacy':backup(LEGACY_KEY,'Beargame-旧存档原始备份.json');break;case 'backup-slot':backup(constants.SAVE_KEY,'Beargame-存档原始备份.json');break;case 'import':if(readOnly||settling){notify('请先在此页继续游戏。');break;}document.querySelector('#save-file').click();break;case 'reload':location.reload();break;case 'takeover':confirmAction('在此页继续照料森林？','另一页会停止推进。本页将重新读取最近保存的进度。',()=>{closeDialog();storageIssue='';if(!claim(true)){renderStatus();notify('没有取得保存权限，请检查浏览器存储设置。');return;}reloadGame();ui.structureKey='';render(true);settlePending();});break;}}
async function importFile(event){if(event.target.id!=='save-file')return;const file=event.target.files?.[0];event.target.value='';if(!file)return;if(file.size>MAX_SAVE_BYTES){notify('文件过大，请选择游戏导出的 JSON 存档。');return;}try{const text=await file.text();parseSave(text);confirmAction('替换当前森林？',`将导入「${file.name}」。当前本章进度会被替换，建议先导出备份。`,()=>{if(readOnly||!ownsLease()||storageIssue||settling){notify('当前无法导入，请检查保存权限。');return;}const result=game.importSave(text);if(result.ok===false){notify(result.message||'无法导入，原存档保持不变。',6000);return;}loadBlocked=false;settlementFailed=false;settlementFailureKind='';settlementFailureMessage='';ui.revealBuilding=null;settings.tracked=null;ui.returnContext=null;ui.actionErrors={};persistUI();closeDialog();lastTick=now();save();ui.structureKey='';render(true);notify(storageIssue?'已读入本页，但保存失败，请立即导出备份。':'存档已导入，欢迎回来。');settlePending();},true);}catch(e){notify('无法导入：'+e.message+'。当前存档未改变。',7000);}}
function onClick(event){const b=event.target.closest('button');if(!b){if(event.target.classList?.contains('dialog-backdrop')&&!settling)cancelDialog();return;}if(b.disabled||settling)return;if(b.dataset.chapterTarget){let [section,id]=b.dataset.chapterTarget.split(':');if(!known(vm[section]?.find(c=>c.id===id))){section='science';id='construction';}if(section==='buildings')ui.buildChoice=id;else{ui.researchTab=section;ui.researchQuery='';ui.researchReady=false;ui.pendingTarget=`[data-research-card="${section}:${id}"]`;}navigate(section==='buildings'?'build':'research');return;}if(b.dataset.track){const [section,id]=b.dataset.track.split(':');if(settings.tracked?.id===id&&settings.tracked?.section===section){settings.tracked=null;persistUI();render(true);}else if(['buildings','crafts'].includes(section))openDialog('target','设置目标数量',{section,id});else{settings.tracked=createTrackedGoal(vm,section,id);persistUI();render(true);notify('已固定当前目标。');}return;}if(b.dataset.pinReplace){settings.pinned=(settings.pinned||[]).map(id=>id===b.dataset.pinReplace?dialog.resource:id);persistUI();hud();openDialog('resources','森林仓库',{resource:dialog.resource});notify('固定资源已替换。');return;}if(b.dataset.pin){const pins=(settings.pinned||[]).filter(id=>id!=='honey');if(b.dataset.pin==='honey')return;if(!pins.includes(b.dataset.pin)&&pins.length>=2){openDialog('pin-replace','替换固定资源',{resource:b.dataset.pin});return;}settings.pinned=pins.includes(b.dataset.pin)?pins.filter(id=>id!==b.dataset.pin):[b.dataset.pin,...pins];persistUI();hud();refreshDialog();notify('固定位置 '+settings.pinned.length+'/2。');return;}if(b.dataset.transferTo){openDialog('transfer','调任'+(vm.jobs.find(j=>j.id===b.dataset.transferTo)?.name||'岗位'),{id:b.dataset.transferTo,amount:1});return;}if(b.dataset.resource){openDialog('resources','森林仓库',{resource:b.dataset.resource});return;}if(b.dataset.nav){if(b.dataset.flow)ui.returnContext=navigationContext();if(b.dataset.jobTarget)ui.pendingTarget=`[data-job-card="${b.dataset.jobTarget}"]`;if(b.dataset.researchTarget){ui.researchQuery='';ui.researchReady=false;ui.pendingTarget=`[data-research-card="${b.dataset.researchChoice||'science'}:${b.dataset.researchTarget}"]`;}if(b.dataset.researchChoice)ui.researchTab=b.dataset.researchChoice;if(b.dataset.buildTarget)ui.buildChoice=b.dataset.buildTarget;navigate(b.dataset.nav);return;}if(b.dataset.region){navigate('home',b.dataset.region);return;}if(b.dataset.queuePage!==undefined){rememberPage();ui.queuePage=Math.max(0,Number(b.dataset.queuePage)||0);render();restorePage();return;}if(b.dataset.buildChoice){ui.buildChoice=b.dataset.buildChoice;render();return;}if(b.dataset.researchTab){rememberPage();ui.researchTab=b.dataset.researchTab;render();restorePage();return;}if(b.dataset.detail){const [section,id]=b.dataset.detail.split(':');openDialog('detail','林间图鉴',{section,id});return;}if(b.dataset.bear){openDialog('bear','林间聊聊',{id:b.dataset.bear});return;}if(b.dataset.act){requestAction(b);return;}if(b.dataset.command)command(b.dataset.command);}
function onKey(event){if(!dialog)return;if(event.key==='Escape'){if(settling)return;event.preventDefault();cancelDialog();return;}if(event.key!=='Tab')return;const list=[...dialogRoot.querySelectorAll('button:not([disabled]),input:not([hidden]),select,summary')].filter(el=>el.offsetParent!==null),first=list[0],last=list.at(-1);if(!first){event.preventDefault();dialogRoot.querySelector('.dialog').focus();return;}if(event.shiftKey&&(document.activeElement===first||!dialogRoot.contains(document.activeElement))){event.preventDefault();last.focus();}else if(!event.shiftKey&&(document.activeElement===last||!dialogRoot.contains(document.activeElement))){event.preventDefault();first.focus();}}
// Deferred offline time must settle before any live tick, including lifecycle flushes.
function flushActive(){const current=now(),seconds=Math.max(0,(current-lastTick)/1000);lastTick=current;if(!canAct()||hiddenAt!==null||seconds<=0)return;const pending=game.snapshot().pendingOffline;if(pending>0){settle(pending);return;}if(seconds>5){if(vm.settings.offline&&!vm.settings.paused){settle(seconds);return;}game.tick(vm.settings.paused?seconds:0);return;}const r=game.tick(seconds);if(r?.ok===false){stopProgress(r.message,'live');notify(settlementFailureMessage,6000);}}
async function settle(seconds){if(!canAct()||!(seconds>0)||!game.snapshot().settings.offline||game.snapshot().settings.paused)return;const interrupted=dialog?{dialog:{...dialog},parent:parentDialog,history:dialogHistory}:null;const finishDialog=()=>{if(interrupted&&(!interrupted.history||dialogHistory)){dialog=interrupted.dialog;parentDialog=interrupted.parent;refreshDialog();}else closeDialog(true);};settling=true;const target=game;openDialog('settling','整理离线收获');renderStatus();try{const result=await target.catchUpAsync(seconds,{onProgress:({progress})=>{const bar=dialogRoot.querySelector('.offline-progress');if(bar)bar.value=progress;writeText('#offline-label',Math.round(progress*100)+'%',dialogRoot);}});settling=false;lastTick=now();if(result.ok===false){stopProgress(result.message,'offline');finishDialog();notify(settlementFailureMessage,7000);render();return;}if(game!==target||!ownsLease()){readOnly=true;finishDialog();render();return;}vm=game.snapshot();save();finishDialog();render();if(document.hidden)hiddenAt=now();else if(result.seconds>30||seconds>30){if(interrupted)notify('离开的收获已经整理好了，原来的页面还在。');else openDialog('offline','离开时的森林');}}catch(error){settling=false;stopProgress('离线结算中断：'+(error?.message||String(error)),'offline');finishDialog();notify(settlementFailureMessage,7000);render();}}
function settlePending(){if(vm.pendingOffline>0&&!readOnly&&!storageIssue&&!loadBlocked)return settle(vm.pendingOffline);}
function step(){if(document.hidden||settling)return;if(!ownsLease()&&!readOnly){readOnly=true;render();}if(canAct())flushActive();else lastTick=now();if(!settling&&canAct()&&now()-lastSave>=15000)save();if(!settling)render();}
function onVisibility(){if(document.hidden){document.documentElement.classList.add('scene-paused');if(canAct()&&!settling&&hiddenAt===null){flushActive();if(!settling){save();hiddenAt=now();}}return;}document.documentElement.classList.remove('scene-paused');if(settling)return;if(!ownsLease()){readOnly=true;lastTick=now();render();return;}if(hiddenAt!==null&&!storageIssue&&!loadBlocked){hiddenAt=null;reloadGame();render();settlePending();}else{lastTick=now();render();}}
function onStorage(event){if(event.key===LEASE_KEY&&!ownsLease()){readOnly=true;lastTick=now();render();}if(event.key===constants.SAVE_KEY&&readOnly&&!settling){reloadGame();render();}}
export const firstScreenAssets=()=>[...new Set([art.scenery.loading,art.scenery.background,art.bears.idleFront,art.buildings.hive,art.buildings.hut,art.resources.honey,art.resources.wood])];
const failedAssets=new Set(),loadedAssets=new Set();
async function loadAsset(src,timeout=12000){return new Promise(resolve=>{const img=new Image();let ended=false;const done=ok=>{if(ended)return;ended=true;clearTimeout(timer);img.onload=img.onerror=null;if(ok){loadedAssets.add(src);failedAssets.delete(src);}else failedAssets.add(src);resolve(ok);};const timer=setTimeout(()=>done(false),timeout);img.onload=async()=>{if(ended)return;try{await img.decode?.();done(true);}catch{done(false);}};img.onerror=()=>done(false);img.src=src;});}
async function preload(){const assets=firstScreenAssets(),progress=document.querySelector('#loading-progress');let complete=0;progress.max=assets.length;await Promise.all(assets.map(async src=>{await loadAsset(src,4000);progress.value=++complete;writeText('#loading-label',`正在准备家园 · ${Math.round(complete/assets.length*100)}%`,document);}));}
function renderArtStatus(){const target=app?.querySelector('#art-status');if(!target)return;const html=failedAssets.size?'<div class="art-status"><span>部分插画暂未显示，家园可以继续生长。</span><button data-command="retry-art">重试插画</button></div>':'';if(target.innerHTML!==html)target.innerHTML=html;}
async function prefetchArt(retry=false){const list=retry?[...failedAssets]:forestAssets.filter(src=>!loadedAssets.has(src)&&!failedAssets.has(src));let index=0;await Promise.all(Array.from({length:Math.min(4,list.length)},async()=>{while(index<list.length){const src=list[index++];await loadAsset(src);renderArtStatus();}}));for(const img of document.querySelectorAll('img[data-art-url]')){const src=img.dataset.artUrl;if(loadedAssets.has(src)&&img.classList.contains('image-failed')){img.classList.remove('image-failed');img.alt='';img.src=src;}}renderArtStatus();}
function imageFailed(event){const img=event.target;if(img?.tagName!=='IMG'||!img.dataset.artUrl)return;failedAssets.add(img.dataset.artUrl);img.classList.add('image-failed');img.alt='插画暂未显示';renderArtStatus();}

async function finishLoading(){
 const screen=document.querySelector('#loading-screen');
 if(screen&&!settings.reducedMotion&&!matchMedia('(prefers-reduced-motion: reduce)').matches){
  // Only the ready loader fades. The rendered home has no second opening scene.
  screen.getBoundingClientRect();
  await new Promise(resolve=>{const done=()=>{clearTimeout(timer);screen.removeEventListener('transitionend',onEnd);resolve();};const onEnd=event=>{if(event.target===screen&&event.propertyName==='opacity')done();};const timer=setTimeout(done,300);screen.addEventListener('transitionend',onEnd);screen.classList.add('loading-complete');});
 }
 screen?.remove();app.removeAttribute('aria-hidden');app.inert=!!dialog;
}
async function boot(){loading=true;app=document.querySelector('#app');dialogRoot=document.querySelector('#dialog-root');document.addEventListener('error',imageFailed,true);try{try{settings={reducedMotion:matchMedia('(prefers-reduced-motion: reduce)').matches,...JSON.parse(readStorage(UI_KEY)||'{}')};}catch{}document.documentElement.classList.toggle('motion-reduced',settings.reducedMotion);applyTextSize();await preload();tabId=globalThis.crypto?.randomUUID?.()||Math.random().toString(36).slice(2);claim();reloadGame();settings.notices=Array.isArray(settings.notices)?settings.notices.filter(n=>n&&typeof n.text==='string').slice(0,20):[];settings.pinned=Array.isArray(settings.pinned)?settings.pinned.filter(id=>id!=='honey'&&vm.resources.some(r=>r.id===id)).slice(0,2):[];settings.tracked=settings.tracked&&['science','workshop','buildings','crafts'].includes(settings.tracked.section)&&vm[settings.tracked.section]?.some(c=>c.id===settings.tracked.id)?settings.tracked:null;completionWasShown=chapterComplete(vm);shell();readHash();render(true);document.addEventListener('click',onClick);document.addEventListener('keydown',onKey);document.addEventListener('change',importFile);document.addEventListener('input',researchInput);document.addEventListener('change',researchInput);document.addEventListener('change',changeAmount);document.addEventListener('input',changeTransfer);document.addEventListener('change',changeTransfer);document.addEventListener('visibilitychange',onVisibility);window.addEventListener('storage',onStorage);window.addEventListener('hashchange',()=>{if(!ui.navigating)rememberPage();ui.navigating=false;closeDialog(true);readHash();render(true);restorePage();});document.addEventListener('scroll',event=>{if(event.target.classList?.contains('world-scene'))syncSceneFocus();},true);document.addEventListener('toggle',event=>{if(event.target.classList?.contains('research-search-tools'))ui.researchTools=event.target.open;},true);window.addEventListener('popstate',()=>{if(settling){dialogHistory=!!history.state?.forestDialog;return;}if(dialog)closeDialog(true);});window.addEventListener('pagehide',()=>{if(ownsLease()&&!settling){if(!document.hidden&&hiddenAt===null){flushActive();if(!settling)save();}if(!settling)try{localStorage.removeItem(LEASE_KEY);}catch{}}});window.addEventListener('pageshow',event=>{if(event.persisted&&!settling){hiddenAt=null;storageIssue='';if(claim()){reloadGame();render(true);settlePending();}else render();}});leaseTimer=setInterval(()=>{if(ownsLease()){if(!writeStorage(LEASE_KEY,JSON.stringify({id:tabId,until:now()+7000})))render();}else if(!readOnly){readOnly=true;render();}},2000);await finishLoading();loading=false;booted=true;renderArtStatus();prefetchArt();settlePending();tickTimer=setInterval(step,200);}catch(error){const label=document.querySelector('#loading-label');if(label)label.textContent='家园还没准备好：'+error.message+' 已有存档不会被删除。';const retry=document.querySelector('#loading-retry');if(retry){retry.hidden=false;retry.onclick=()=>location.reload();}document.documentElement.classList.add('motion-reduced');}}
if(typeof document!=='undefined'&&document.querySelector('#app'))boot();
